import React from "react";

// ——— Images (mets les bons chemins vers tes PNG) ———
import AccelLogo from "assets/img/accel_logo.png";
import IconLink from "assets/img/link.png";
import IconPhone from "assets/img/phone.png";
import IconMail from "assets/img/mail.png";
import IconGlobe from "assets/img/globe.png";
// NOTE : Assurez-vous que ces images sont ORANGES comme dans le design !
import IconFb from "assets/img/facebook.png";
import IconIn from "assets/img/link.png";
import IconYt from "assets/img/youtube.png";

export default function Footer() {
  return (
    // Couleur de fond : Bleu foncé du design
    <footer
      className="bg-[#1e204a] text-white"
      style={{ backgroundColor: '#1e204a' }}
    >
      {/* Partie haute avec 4 colonnes */}
      {/* CHANGEMENT ICI : Passage à grid-cols-4 */}
      <div className="max-w-[1280px] mx-auto px-6 lg:px-12 py-16 lg:py-20 grid grid-cols-1 md:grid-cols-4 gap-8 lg:gap-12">

        {/* Col 1 : Powered By (1/4) */}
        <div className="flex flex-col items-start text-left">
          <h3 className="text-[28px] font-bold mb-8">Powered By</h3>
          <img
            src={AccelLogo}
            alt="Accel"
            className="h-16 w-16 object-contain"
          />
        </div>

        {/* Col 2 : Liens utiles 1 (1/4) */}
        {/* Suppression des icônes sociales ici */}
        <div className="flex flex-col items-start">
          <h3 className="text-[24px] font-semibold mb-8">Liens utiles</h3>

          <ul className="space-y-7">
            <li className="flex items-center gap-4">
              <img src={IconLink} alt="" className="h-6 w-6 object-contain opacity-90" />
              <a href="#" className="text-lg hover:underline">
                Red Hat Enterprise Linux
              </a>
            </li>
            <li className="flex items-center gap-4">
              <img src={IconLink} alt="" className="h-6 w-6 object-contain opacity-90" />
              <a href="#" className="text-lg hover:underline">
                Openshift AI
              </a>
            </li>
            <li className="flex items-center gap-4">
              <img src={IconLink} alt="" className="h-6 w-6 object-contain opacity-90" />
              <a href="#" className="text-lg hover:underline">
                Heritage Cloud
              </a>
            </li>
          </ul>
        </div>

        {/* NOUVELLE Col 3 : Liens Utiles 2 / Icônes sociales (1/4) */}
        {/* On crée une nouvelle colonne et on y met les icônes sociales pour séparer */}
        <div className="flex flex-col items-start">
          <h3 className="text-[24px] font-semibold mb-8">Autres liens</h3>
          <ul className="space-y-7 mb-16">
            <li className="flex items-center gap-4">
              <img src={IconLink} alt="" className="h-6 w-6 object-contain opacity-90" />
              <a href="#" className="text-lg hover:underline">Lien Supplémentaire A</a>
            </li>
            <li className="flex items-center gap-4">
              <img src={IconLink} alt="" className="h-6 w-6 object-contain opacity-90" />
